px 16px}.btn-primary{--bs-btn-bg:var(--green);--bs-btn-border-color:var(--green);--bs-btn-hover-bg:var(--green-dark);--bs-btn-hover-border-color:var(--green-dark)}.btn-outline-primary{--bs-btn-color:var(--green);--bs-btn-border-color:#b8d5c8;--bs-btn-hover-bg:var(--green);--bs-btn-hover-border-color:var(--green)}.card-panel{background:#fff;border:1px solid var(--line);border-radius:15px;box-shadow:0 5px 20px rgba(31,58,45,.025)}.table{margin:0}.table thead th{font-size:10px;text-transform:uppercase;letter-spacing:.09em;color:#87938d;font-weight:700;background:#fafcfb;border-bottom-color:var(--line);padding:14px 18px;white-space:nowrap}.table td{padding:16px 18px;border-bottom-color:#eef1ef;vertical-align:middle}.table tbody tr:last-child td{border-bottom:0}.entity-title{font-weight:700;color:var(--ink)}.entity-sub{font-size:12px;color:var(--muted);margin-top:3px}.badge-status{display:inline-flex;align-items:center;gap:7px;padding:6px 10px;border-radius:50px;font-size:11px;font-weight:700}.badge-status:before{content:'';width:6px;height:6px;border-radius:50%;background:currentColor}.status-on{color:#187a5b;background:#eaf5ef}.status-off{color:#78827d;background:#f0f2f1}.action-link{padding:6px 9px;color:#627069;border-radius:7px;border:0;background:transparent;font-weight:600;font-size:13px}.action-link:hover{background:#f1f5f2;color:var(--green)}.action-delete:hover{background:#fff0ef;color:#bd4338}.empty-state{text-align:center;padding:60px 20px;color:var(--muted)}.empty-icon{margin:0 auto 14px;width:52px;height:52px;border-radius:16px;background:#edf6f1;color:var(--green);display:grid;place-items:center;font-size:23px}.form-card{max-width:760px;padding:26px}.form-label{font-weight:700;font-size:13px;margin-bottom:7px}.form-control,.form-select{border-color:#dfe6e2;border-radius:9px;padding:11px 13px}.form-control:focus,.form-select:focus{border-color:#88bca5;box-shadow:0 0 0 .2rem rgba(24,122,91,.12)}.form-text{color:#8a9690}.form-check-input:checked{background-color:var(--green);border-color:var(--green)}.alert{border:0;border-radius:10px}.hero-panel{min-height:258px;border-radius:18px;background:linear-gradient(115deg,#155f49,#1b8b64);color:#fff;padding:38px 42px;display:flex;justify-content:space-between;align-items:center;overflow:hidden;position:relative}.hero-panel .eyebrow{color:#b9e6d0}.hero-panel h1{font-size:clamp(30px,4vw,44px);max-width:500px}.hero-panel p{color:#d2eadc;margin:0}.hero-decoration{position:absolute;right:8%;font-size:240px;line-height:1;color:rgba(255,255,255,.07);transform:rotate(-15deg)}.hero-copy{z-index:1}.stat-card{height:100%;min-height:166px;background:#fff;border:1px solid var(--line);border-radius:14px;padding:20px;display:flex;flex-direction:column;color:var(--ink)}.stat-card:hover{transform:translateY(-2px);box-shadow:0 10px 25px rgba(31,58,45,.07)}.stat-icon{width:36px;height:36px;border-radius:11px;display:grid;place-items:center;font-size:19px;margin-bottom:14px}.icon-lilac{background:#f1edfb;color:#7863b4}.icon-mint{background:#e8f5ef;color:#25865f}.icon-amber{background:#fff4df;color:#b27a16}.stat-label{font-size:12px;color:var(--muted)}.stat-card strong{font-family:Manrope,sans-serif;font-size:29px;margin-top:2px}.stat-link{font-size:11px;font-weight:700;color:var(--green);margin-top:auto}.section-heading{display:flex;justify-content:space-between;align-items:center}.quick-actions{background:#fff;border:1px solid var(--line);border-radius:14px;padding:23px 25px;display:flex;align-items:center;justify-content:space-between;gap:20px}.pagination{margin:0}.page-link{color:var(--green);border-color:var(--line)}.active>.page-link,.page-link.active{background:var(--green);border-color:var(--green)}.mobile-nav{display:none}
